package com.lbos.commercecustomer.service; import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.client.PlatformTerritoryClient;import com.lbos.commercecustomer.dto.client.platform.TerritoryValidationResponse;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.exception.BusinessValidationException;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.CustomerAddressRepository;import com.lbos.commercecustomer.repository.CustomerCartItemRepository;import com.lbos.commercecustomer.service.impl.*;import java.util.*;import org.junit.jupiter.api.Test; class AddressServiceImplTest {@Test void onlyDefaultCannotBeDeleted(){var repo=mock(CustomerAddressRepository.class);var ctx=mock(ContextSupport.class);var platform=mock(PlatformTerritoryClient.class);var service=new AddressServiceImpl(repo,ctx,platform,new CommerceMapper(),new FeignCallSupport(),mock(CustomerCartItemRepository.class));var c=new CustomerProfile();c.setId(UUID.randomUUID());var a=new CustomerAddress();a.setId(UUID.randomUUID());a.setCustomer(c);a.setDefaultAddress(true);when(ctx.customer()).thenReturn(c);when(repo.findByIdAndCustomerId(a.getId(),c.getId())).thenReturn(Optional.of(a));when(repo.findByCustomerIdOrderByIdAsc(c.getId())).thenReturn(List.of(a));assertThrows(BusinessValidationException.class,()->service.delete(a.getId()));}@Test void deletionReassignsDefault(){var repo=mock(CustomerAddressRepository.class);var ctx=mock(ContextSupport.class);var service=new AddressServiceImpl(repo,ctx,mock(PlatformTerritoryClient.class),new CommerceMapper(),new FeignCallSupport(),mock(CustomerCartItemRepository.class));var c=new CustomerProfile();c.setId(UUID.randomUUID());var a=new CustomerAddress();a.setId(UUID.randomUUID());a.setCustomer(c);a.setDefaultAddress(true);var b=new CustomerAddress();b.setId(UUID.randomUUID());b.setCustomer(c);when(ctx.customer()).thenReturn(c);when(repo.findByIdAndCustomerId(a.getId(),c.getId())).thenReturn(Optional.of(a));when(repo.findByCustomerIdOrderByIdAsc(c.getId())).thenReturn(List.of(a,b));service.delete(a.getId());assertTrue(b.isDefaultAddress());verify(repo).save(b);}}